@app.cell
def _(mo):
    complete_extraction_script = '"""Stream, flatten, deduplicate and reproducibly sample winddude listings.\n\nRun from the repository root. Original data is never modified. SQLite keeps\ndeduplication on disk; reservoir sampling operates on unique eligible listings.\nThe SQLite intermediate is reusable for a different sample size or seed.\n"""\nfrom __future__ import annotations\n\nimport argparse\nfrom collections import Counter\nfrom datetime import datetime, timezone\nimport hashlib\nimport importlib.metadata\nimport json\nimport math\nfrom pathlib import Path\nimport random\nimport re\nimport shutil\nimport sqlite3\nimport sys\nimport time\nfrom urllib.parse import urlsplit, urlunsplit\n\nROOT = Path(__file__).resolve().parents[1]\nif (ROOT / ".pipeline_deps").exists():\n    sys.path.insert(0, str(ROOT / ".pipeline_deps"))\nimport ijson\nimport pandas as pd\n\nFIELDS = [\n    "listing_key", "source_record_id", "date_posted", "date_last_crawled",\n    "posting_year", "country", "state_code", "latitude", "longitude",\n    "make_model_raw", "model_year", "manufacturer", "body_style_raw",\n    "body_style", "transmission", "price_usd", "currency_code", "mileage_raw",\n    "vehicle_age", "next_model_year", "is_japanese_brand", "brand_match_status",\n]\nBRANDS = {\n    "acura": ["acura"], "alfa-romeo": ["alfa romeo"], "aston-martin": ["aston martin"],\n    "audi": ["audi"], "bentley": ["bentley"], "bmw": ["bmw"], "buick": ["buick"],\n    "cadillac": ["cadillac"], "chevrolet": ["chevrolet", "chevy"], "chrysler": ["chrysler"],\n    "dodge": ["dodge"], "ferrari": ["ferrari"], "fiat": ["fiat"], "ford": ["ford"],\n    "genesis": ["genesis"], "gmc": ["gmc"], "honda": ["honda"], "hyundai": ["hyundai"],\n    "infiniti": ["infiniti"], "isuzu": ["isuzu"], "jaguar": ["jaguar"], "jeep": ["jeep"],\n    "kia": ["kia"], "lamborghini": ["lamborghini"], "land-rover": ["land rover", "range rover"],\n    "lexus": ["lexus"], "lincoln": ["lincoln"], "lotus": ["lotus"], "maserati": ["maserati"],\n    "mazda": ["mazda"], "mercedes-benz": ["mercedes benz", "mercedes"], "mercury": ["mercury"],\n    "mini": ["mini cooper", "mini"], "mitsubishi": ["mitsubishi"], "nissan": ["nissan", "datsun"],\n    "oldsmobile": ["oldsmobile"], "plymouth": ["plymouth"], "pontiac": ["pontiac"],\n    "porsche": ["porsche"], "ram": ["ram"], "rolls-royce": ["rolls royce"], "saab": ["saab"],\n    "saturn": ["saturn"], "scion": ["scion"], "smart": ["smart"], "subaru": ["subaru"],\n    "suzuki": ["suzuki"], "tesla": ["tesla"], "toyota": ["toyota"],\n    "volkswagen": ["volkswagen", "vw"], "volvo": ["volvo"],\n}\nJAPANESE = {"acura", "honda", "infiniti", "isuzu", "lexus", "mazda", "mitsubishi", "nissan", "scion", "subaru", "suzuki", "toyota"}\nPATTERNS = [(name, re.compile(r"\\b(?:" + "|".join(re.escape(a) for a in aliases) + r")\\b"))\n            for name, aliases in BRANDS.items()]\nBODY_STYLES = {\n    "sedan": "sedan", "suv": "suv", "pickup": "pickup", "truck": "truck",\n    "coupe": "coupe", "convertible": "convertible", "hatchback": "hatchback",\n    "wagon": "wagon", "van": "van", "mini van": "minivan", "minivan": "minivan",\n    "offroad": "offroad", "off road": "offroad", "bus": "bus", "other": "other",\n}\n\n\ndef mapping(value):\n    return value if isinstance(value, dict) else {}\n\n\ndef text(value):\n    if value is None:\n        return None\n    result = str(value).strip()\n    return result or None\n\n\ndef number(value):\n    try:\n        if isinstance(value, bool):\n            return None\n        result = float(value)\n        return result if math.isfinite(result) else None\n    except (ValueError, TypeError, OverflowError):\n        return None\n\n\ndef parse_date(value):\n    try:\n        return datetime.fromisoformat(str(value).strip().replace("Z", "+00:00"))\n    except (ValueError, TypeError):\n        return None\n\n\ndef normalize_words(value):\n    return re.sub(r"[^a-z0-9]+", " ", (text(value) or "").lower()).strip()\n\n\ndef brand_from_model(value):\n    words = normalize_words(value)\n    # Remove a leading year; match a brand at the start to avoid brand names\n    # mentioned in descriptive comparisons later in a make/model string.\n    words = re.sub(r"^(?:19|20)\\d{2}\\s+", "", words)\n    candidates = [brand for brand, pattern in PATTERNS if pattern.match(words)]\n    if "dodge" in candidates and re.match(r"dodge ram\\b", words):\n        return "dodge", "matched"\n    if len(candidates) == 1:\n        return candidates[0], "matched"\n    return None, "ambiguous" if candidates else ("missing" if not words else "unrecognized")\n\n\ndef identity(record, source):\n    url = text(source.get("url"))\n    if url:\n        parsed = urlsplit(url)\n        if parsed.scheme in {"http", "https"} and parsed.netloc:\n            canonical = urlunsplit(("https", parsed.netloc.lower(), parsed.path.rstrip("/"), "", ""))\n            return hashlib.sha256(("url:" + canonical).encode()).hexdigest()\n    record_id = text(record.get("_id"))\n    return hashlib.sha256(("id:" + record_id).encode()).hexdigest() if record_id else None\n\n\ndef flatten(record, year, audit, diagnostics):\n    audit["raw_records"] += 1\n    if not isinstance(record, dict):\n        audit["invalid_record_object"] += 1\n        return None\n    source = mapping(record.get("_source"))\n    location = mapping(source.get("location"))\n    country = (text(location.get("country")) or "").upper()\n    diagnostics["raw_country_counts"][country or "missing"] += 1\n    if country != "US":\n        return None\n    audit["after_us_filter"] += 1\n    posted = parse_date(source.get("date_posted"))\n    diagnostics["us_posting_year_counts"][str(posted.year) if posted else "invalid_or_missing"] += 1\n    if posted is None or posted.year != year:\n        return None\n    audit["after_posting_year_filter"] += 1\n    coords = mapping(location.get("lat_long"))\n    latitude, longitude = number(coords.get("lat")), number(coords.get("lon"))\n    if latitude is None or longitude is None or not -90 <= latitude <= 90 or not -180 <= longitude <= 180 or (latitude == 0 and longitude == 0):\n        return None\n    audit["after_valid_coordinates"] += 1\n    key = identity(record, source)\n    if key is None:\n        return None\n    audit["after_listing_identity"] += 1\n    vehicle, specifications, price = (mapping(source.get(k)) for k in ["vehicle", "specifications", "price"])\n    model = text(vehicle.get("make_model"))\n    manufacturer, brand_status = brand_from_model(model)\n    diagnostics["eligible_brand_match_counts"][brand_status] += 1\n    model_year = number(vehicle.get("year"))\n    if model_year is not None and (not model_year.is_integer() or not 1886 <= model_year <= year + 1):\n        audit["invalid_model_year_set_missing"] += 1\n        model_year = None\n    model_year = int(model_year) if model_year is not None else None\n    next_model = model_year == year + 1\n    if next_model:\n        audit["next_model_year_age_missing"] += 1\n    age = year - model_year if model_year is not None and not next_model else None\n    amount = number(price.get("usd_price"))\n    if amount is not None and amount <= 0:\n        audit["nonpositive_price_set_missing"] += 1\n        amount = None\n    mileage = number(source.get("mileage"))\n    if mileage is not None and mileage < 0:\n        audit["negative_mileage_set_missing"] += 1\n        mileage = None\n    raw_body = text(specifications.get("body_style"))\n    body = BODY_STYLES.get(normalize_words(raw_body))\n    transmission = (text(specifications.get("transmission")) or "").lower() or None\n    region = text(mapping(location.get("source")).get("region"))\n    state = region[3:].upper() if region and re.fullmatch(r"US-[A-Za-z]{2}", region) else None\n    crawled = parse_date(source.get("date_last_crawled"))\n    ranked = crawled or posted\n    rank = ranked.replace(tzinfo=timezone.utc) if ranked.tzinfo is None else ranked.astimezone(timezone.utc)\n    result = dict(zip(FIELDS, [\n        key, text(record.get("_id")), text(source.get("date_posted")), text(source.get("date_last_crawled")),\n        year, country, state, latitude, longitude, model, model_year, manufacturer,\n        raw_body, body, transmission, amount, text(price.get("currency_code")), mileage,\n        age, next_model, manufacturer in JAPANESE if manufacturer else None, brand_status,\n    ]))\n    for column, value in result.items():\n        if value is None:\n            diagnostics["eligible_missing_counts_before_dedup"][column] += 1\n    return result, rank.isoformat()\n\n\ndef scan(source_path, database, year, batch_size, progress_seconds):\n    if database.exists():\n        raise FileExistsError(f"Intermediate exists: {database}; use --reuse-intermediate after a completed scan.")\n    connection = sqlite3.connect(database)\n    connection.execute("PRAGMA journal_mode=DELETE")\n    connection.execute("PRAGMA temp_store=FILE")\n    connection.execute("PRAGMA cache_size=-1048576")\n    # Keep large payloads in append-oriented table pages, with a separate narrow\n    # key index. A WITHOUT ROWID table would random-write the entire payload\n    # B-tree on each hash key and become much slower as the table grows.\n    connection.execute("CREATE TABLE listings (listing_key TEXT UNIQUE NOT NULL, crawl_rank TEXT, state_code TEXT, payload TEXT)")\n    connection.execute("CREATE TABLE metadata (key TEXT PRIMARY KEY, value TEXT)")\n    audit = Counter()\n    diagnostics = {name: Counter() for name in ["raw_country_counts", "us_posting_year_counts", "eligible_brand_match_counts", "eligible_missing_counts_before_dedup"]}\n    sql = """INSERT INTO listings VALUES (?,?,?,?) ON CONFLICT(listing_key) DO UPDATE SET\n             crawl_rank=excluded.crawl_rank, state_code=excluded.state_code, payload=excluded.payload\n             WHERE excluded.crawl_rank >= listings.crawl_rank"""\n    batch = []\n    start = last = time.monotonic()\n    try:\n        with source_path.open("rb") as stream:\n            for record in ijson.items(stream, "item", use_float=True):\n                flattened = flatten(record, year, audit, diagnostics)\n                if flattened:\n                    row, rank = flattened\n                    batch.append((row["listing_key"], rank, row["state_code"], json.dumps(row, separators=(",", ":"), ensure_ascii=False)))\n                if len(batch) >= batch_size:\n                    connection.executemany(sql, batch)\n                    connection.commit()\n                    batch.clear()\n                now = time.monotonic()\n                if now - last >= progress_seconds:\n                    print(f"Scan {stream.tell()/source_path.stat().st_size:.1%}: {audit[\'raw_records\']:,} records read; {audit[\'after_listing_identity\']:,} eligible before dedup; elapsed {int(now-start)}s", flush=True)\n                    if shutil.disk_usage(database.parent).free < 1024**3:\n                        raise RuntimeError("Less than 1 GiB free; partial intermediate retained, scan not marked complete.")\n                    last = now\n        if batch:\n            connection.executemany(sql, batch)\n            connection.commit()\n        unique = connection.execute("SELECT COUNT(*) FROM listings").fetchone()[0]\n        audit["after_deduplication"] = unique\n        audit["duplicate_eligible_records_removed"] = audit["after_listing_identity"] - unique\n        metadata = {\n            "scan_complete": True, "source_path": str(source_path.resolve()),\n            "source_bytes": source_path.stat().st_size, "source_mtime_ns": source_path.stat().st_mtime_ns,\n            "posting_year": year, "audit": dict(audit), "diagnostics": {k: dict(v) for k, v in diagnostics.items()},\n            "scan_seconds": round(time.monotonic() - start, 1),\n        }\n        connection.execute("INSERT INTO metadata VALUES (?,?)", ("scan", json.dumps(metadata)))\n        connection.commit()\n        print(f"Scan complete: {unique:,} unique eligible listings", flush=True)\n        return metadata\n    finally:\n        connection.close()\n\n\ndef sample(database, source_path, output_dir, report_dir, size, seed, year):\n    connection = sqlite3.connect(database)\n    metadata_row = connection.execute("SELECT value FROM metadata WHERE key=\'scan\'").fetchone()\n    if not metadata_row:\n        raise RuntimeError("Intermediate scan is incomplete; cannot use it for sampling.")\n    metadata = json.loads(metadata_row[0])\n    if metadata["posting_year"] != year or metadata["source_bytes"] != source_path.stat().st_size or metadata["source_mtime_ns"] != source_path.stat().st_mtime_ns:\n        raise RuntimeError("Intermediate does not match the requested source/year.")\n    generator = random.Random(seed)\n    reservoir = []\n    total = metadata["audit"]["after_deduplication"]\n    population_missing = Counter()\n    population_brand = Counter()\n    start = last = time.monotonic()\n    # Deterministic insertion order avoids random disk reads of every payload.\n    # Rebuilding from the same input and rules produces the same rowid order.\n    for seen, (payload,) in enumerate(connection.execute("SELECT payload FROM listings ORDER BY rowid"), 1):\n        row = json.loads(payload)\n        population_missing.update(k for k, v in row.items() if v is None)\n        population_brand[row["manufacturer"] or "unknown"] += 1\n        if seen <= size:\n            reservoir.append(row)\n        else:\n            position = generator.randrange(seen)\n            if position < size:\n                reservoir[position] = row\n        now = time.monotonic()\n        if now - last >= 20:\n            print(f"Sampling {seen/total:.1%}: {seen:,}/{total:,} unique records", flush=True)\n            last = now\n    frame = pd.DataFrame(reservoir, columns=FIELDS)\n    for col in ["model_year", "posting_year", "vehicle_age"]:\n        frame[col] = pd.array(frame[col], dtype="Int64")\n    for col in ["next_model_year", "is_japanese_brand"]:\n        frame[col] = pd.array(frame[col], dtype="boolean")\n    output_dir.mkdir(parents=True, exist_ok=True)\n    report_dir.mkdir(parents=True, exist_ok=True)\n    destination = output_dir / "vehicles_us_2019_sample.parquet"\n    frame.to_parquet(destination, index=False, compression="zstd")\n    audit = metadata["audit"]\n    stages = ["raw_records", "after_us_filter", "after_posting_year_filter", "after_valid_coordinates", "after_listing_identity", "after_deduplication"]\n    previous = None\n    records = []\n    for stage in stages:\n        count = audit.get(stage, 0)\n        records.append({"step": stage, "rows": count, "removed_since_previous": None if previous is None else previous - count})\n        previous = count\n    records.append({"step": "random_sample", "rows": len(frame), "removed_since_previous": total - len(frame)})\n    pd.DataFrame(records).to_csv(report_dir / "automotive_processing_audit.csv", index=False)\n    pd.DataFrame([{"column": col, "population_missing": population_missing[col], "population_missing_share": population_missing[col]/total if total else None,\n                   "sample_missing": int(frame[col].isna().sum()), "sample_missing_share": float(frame[col].isna().mean())} for col in FIELDS]).to_csv(report_dir / "automotive_missingness.csv", index=False)\n    population_state = dict(connection.execute("SELECT COALESCE(state_code,\'unknown\'), COUNT(*) FROM listings GROUP BY COALESCE(state_code,\'unknown\')"))\n    sample_state = frame["state_code"].fillna("unknown").value_counts().to_dict()\n    pd.DataFrame([{"state_code": state, "population_listings": count, "sample_listings": sample_state.get(state,0), "population_share": count/total,\n                   "sample_share": sample_state.get(state,0)/len(frame) if len(frame) else None} for state,count in sorted(population_state.items())]).to_csv(report_dir / "automotive_state_coverage.csv", index=False)\n    sample_brand = frame["manufacturer"].fillna("unknown").value_counts().to_dict()\n    pd.DataFrame([{"manufacturer": brand, "population_listings": count, "sample_listings": sample_brand.get(brand,0), "population_share": count/total,\n                   "sample_share": sample_brand.get(brand,0)/len(frame) if len(frame) else None} for brand,count in sorted(population_brand.items())]).to_csv(report_dir / "automotive_brand_coverage.csv", index=False)\n    digest = hashlib.sha256(destination.read_bytes()).hexdigest()\n    metadata.update({"sample_method": "uniform reservoir sample without replacement after deduplication; deterministic SQLite insertion order",\n                     "seed": seed, "requested_sample_size": size, "sample_rows": len(frame), "sample_columns": len(frame.columns),\n                     "eligible_unique_listings": total, "inclusion_probability": min(size/total,1) if total else None,\n                     "sample_path": str(destination.resolve()), "sample_bytes": destination.stat().st_size, "sample_sha256": digest,\n                     "generated_at_utc": datetime.now(timezone.utc).isoformat(),\n                     "script_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),\n                     "libraries": {name: importlib.metadata.version(name) for name in ["ijson", "pandas", "pyarrow"]},\n                     "brand_aliases": BRANDS, "japanese_brand_list": sorted(JAPANESE), "body_style_mapping": BODY_STYLES,\n                     "limitations": ["Mileage unit has not been verified; mileage_raw is not used in the research questions.",\n                                     "Coordinates are range-checked, not verified against US boundaries.",\n                                     "Brand extraction is conservative and provisional; unknown/ambiguous models remain missing.",\n                                     "Simple random sampling does not ensure sufficient listings near every university.",\n                                     "Next-model-year listings retain model year but have missing vehicle_age."]})\n    (report_dir / "automotive_sample_metadata.json").write_text(json.dumps(metadata, indent=2), encoding="utf-8")\n    connection.close()\n    print(f"Saved {len(frame):,} rows, {len(frame.columns)} columns; {destination.stat().st_size/1024**2:.1f} MiB to {destination}", flush=True)\n    return frame\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("--source", type=Path, default=ROOT / "data/raw/winddude_automotive_2019_2020/extracted/dump1.json")\n    parser.add_argument("--database", type=Path, default=ROOT / "data/processed/automotive_us_2019.sqlite")\n    parser.add_argument("--output-dir", type=Path, default=ROOT / "data/processed")\n    parser.add_argument("--report-dir", type=Path, default=ROOT / "outputs")\n    parser.add_argument("--year", type=int, default=2019)\n    parser.add_argument("--sample-size", type=int, default=500000)\n    parser.add_argument("--seed", type=int, default=6182019)\n    parser.add_argument("--batch-size", type=int, default=10000)\n    parser.add_argument("--progress-seconds", type=int, default=20)\n    parser.add_argument("--reuse-intermediate", action="store_true")\n    args = parser.parse_args()\n    if args.sample_size <= 0 or args.batch_size <= 0:\n        parser.error("sample-size and batch-size must be positive")\n    destination = args.output_dir / "vehicles_us_2019_sample.parquet"\n    if destination.exists():\n        raise FileExistsError(f"Sample exists: {destination}; choose a different --output-dir to retain it.")\n    args.database.parent.mkdir(parents=True, exist_ok=True)\n    if not args.reuse_intermediate:\n        scan(args.source, args.database, args.year, args.batch_size, args.progress_seconds)\n    sample(args.database, args.source, args.output_dir, args.report_dir, args.sample_size, args.seed, args.year)\n\n\nif __name__ == "__main__":\n    main()\n'
    mo.output.append(mo.accordion({'Complete original extraction, cleaning, deduplication, and reservoir-sampling script': mo.md('```python\n' + complete_extraction_script + '\n```')}))
    return (complete_extraction_script,)

@app.cell
def _(pd, np, hd_raw, ef_raw, vehicles_raw, BallTree):
    hd = hd_raw.rename(columns=lambda c: c.strip()).copy()
    ef = ef_raw.rename(columns=lambda c: c.strip()).copy()
    hd['ACT'] = hd['ACT'].astype('string').str.strip()
    us_states = set('AL AK AZ AR CA CO CT DE FL GA HI ID IL IN IA KS KY LA ME MD MA MI MN MS MO MT NE NV NH NJ NM NY NC ND OH OK OR PA RI SC SD TN TX UT VT VA WA WV WI WY DC'.split())
    school_audit = [{'step': 'HD original', 'rows': len(hd)}]
    college_candidates = hd[hd.STABBR.isin(us_states)].copy()
    school_audit.append({'step': 'US 50 states and DC', 'rows': len(college_candidates)})
    college_candidates = college_candidates[college_candidates.ICLEVEL.eq(1) & college_candidates.DEGGRANT.eq(1)]
    school_audit.append({'step': 'Four-year degree-granting', 'rows': len(college_candidates)})
    college_candidates = college_candidates[college_candidates.ACT.isin(['A', 'N', 'R'])].copy()
    school_audit.append({'step': 'Active/new/restored institutions', 'rows': len(college_candidates)})
    assert not hd.UNITID.duplicated().any()
    assert not ef.duplicated(['UNITID', 'EFALEVEL']).any()
    _tot = ef[ef.EFALEVEL.eq(1)][['UNITID', 'EFTOTLT', 'EFTOTLW', 'EFNRALT']]
    _ug = ef[ef.EFALEVEL.eq(2)][['UNITID', 'EFTOTLT']].rename(columns={'EFTOTLT': 'undergraduate_students'})
    _gr = ef[ef.EFALEVEL.eq(12)][['UNITID', 'EFTOTLT']].rename(columns={'EFTOTLT': 'graduate_students'})
    college_candidates = college_candidates.merge(_tot, on='UNITID', how='left', validate='one_to_one', indicator=True)
    enrollment_match_counts = college_candidates['_merge'].value_counts().rename_axis('status').reset_index(name='institutions')
    college_candidates = college_candidates.merge(_ug, on='UNITID', how='left', validate='one_to_one').merge(_gr, on='UNITID', how='left', validate='one_to_one')
    _infer_zero = college_candidates.graduate_students.isna() & college_candidates.undergraduate_students.eq(college_candidates.EFTOTLT) & college_candidates.EFTOTLT.notna()
    college_candidates.loc[_infer_zero, 'graduate_students'] = 0
    inferred_zero_graduate_count = int(_infer_zero.sum())
    colleges = college_candidates[college_candidates.EFTOTLT.gt(0) & college_candidates.LATITUDE.between(-90, 90) & college_candidates.LONGITUD.between(-180, 180)].copy()
    school_audit.append({'step': 'Positive reported enrollment and valid coordinates', 'rows': len(colleges)})
    colleges = colleges.rename(columns={'UNITID': 'unitid', 'INSTNM': 'institution_name', 'STABBR': 'state_code', 'LATITUDE': 'latitude', 'LONGITUD': 'longitude', 'EFTOTLT': 'total_students', 'EFNRALT': 'international_students', 'EFTOTLW': 'female_students'})
    colleges['international_student_share'] = colleges.international_students / colleges.total_students
    colleges['graduate_student_share'] = colleges.graduate_students / colleges.total_students
    vehicles = vehicles_raw.drop_duplicates('listing_key').copy()
    vehicles = vehicles[vehicles.country.eq('US') & vehicles.posting_year.eq(2019) & vehicles.latitude.between(-90, 90) & vehicles.longitude.between(-180, 180)].reset_index(drop=True)
    vehicle_audit = pd.DataFrame([{'step': 'Embedded partial sample', 'rows': len(vehicles_raw)}, {'step': 'Listing-key deduplication', 'rows': len(vehicles_raw.drop_duplicates('listing_key'))}, {'step': 'Revalidated US/year/coordinates', 'rows': len(vehicles)}])
    earth_miles = 3958.7613
    vehicle_tree = BallTree(np.radians(vehicles[['latitude', 'longitude']].to_numpy(dtype=float)), metric='haversine')
    college_points = np.radians(colleges[['latitude', 'longitude']].to_numpy(dtype=float))
    college_tree = BallTree(college_points, metric='haversine')

    def link_radius(radius):
        neighbors, distances = vehicle_tree.query_radius(college_points, r=radius / earth_miles, return_distance=True)
        lengths = np.array([len(n) for n in neighbors])
        return pd.DataFrame({'unitid': np.repeat(colleges.unitid.to_numpy(), lengths), 'vehicle_index': np.concatenate(neighbors).astype(int), 'distance_miles': np.concatenate(distances) * earth_miles})

    def summarize_radius(radius, listing_frame=None):
        pairs = link_radius(radius)
        nearby = pairs.merge(vehicles.reset_index().rename(columns={'index': 'vehicle_index'}), on='vehicle_index', validate='many_to_one')
        if listing_frame is not None:
            nearby = nearby[nearby.listing_key.isin(listing_frame.listing_key)]
        counts = nearby.groupby('unitid').agg(n_listings=('listing_key', 'size'), n_known_brand=('manufacturer', 'count'), n_known_body_style=('body_style', 'count'), n_known_vehicle_age=('vehicle_age', 'count'), vehicle_age_median=('vehicle_age', 'median'), vehicle_age_q25=('vehicle_age', lambda x: x.quantile(0.25)), vehicle_age_q75=('vehicle_age', lambda x: x.quantile(0.75)))
        jp = nearby.assign(japanese=nearby.is_japanese_brand.eq(True).astype(int)).groupby('unitid').japanese.sum()
        counts['n_japanese_brand'] = jp
        counts['japanese_brand_share'] = counts.n_japanese_brand / counts.n_known_brand.replace(0, np.nan)
        for column, prefix, denominator in [('manufacturer', 'brand_share_', 'n_known_brand'), ('body_style', 'body_style_share_', 'n_known_body_style')]:
            distribution = nearby.groupby(['unitid', column]).size().unstack(fill_value=0)
            counts = counts.join(distribution.div(counts[denominator].replace(0, np.nan), axis=0).add_prefix(prefix))
        result = colleges[['unitid', 'institution_name', 'state_code', 'latitude', 'longitude', 'total_students', 'international_students', 'graduate_students', 'international_student_share', 'graduate_student_share']].merge(counts.reset_index(), on='unitid', how='left', validate='one_to_one')
        count_columns = [c for c in result if c.startswith('n_')]
        result[count_columns] = result[count_columns].fillna(0).astype(int)
        result['nearby_college_count'] = college_tree.query_radius(college_points, r=radius / earth_miles, count_only=True)
        result['college_density_per_sq_mile'] = result.nearby_college_count / (np.pi * radius ** 2)
        result['radius_miles'] = radius
        return (result, nearby)
    merged, listing_links = summarize_radius(10)
    alternative_5mi, links_5mi = summarize_radius(5)
    complete_listings = vehicles.dropna(subset=['manufacturer', 'body_style', 'vehicle_age'])
    complete_case_market, _ = summarize_radius(10, complete_listings)
    school_audit = pd.DataFrame(school_audit)
    return (colleges, vehicles, merged, listing_links, alternative_5mi, links_5mi, complete_case_market, complete_listings, school_audit, vehicle_audit, enrollment_match_counts, inferred_zero_graduate_count)

@app.cell
def _(mo, school_audit, vehicle_audit, enrollment_match_counts, merged, listing_links, vehicles, inferred_zero_graduate_count, pd):
    mo.output.append(mo.vstack([mo.md('### Cleaning and enrollment merge audit'), mo.ui.table(school_audit, selection=None), mo.ui.table(vehicle_audit, selection=None), mo.ui.table(enrollment_match_counts, selection=None)]))
    spatial_audit = pd.DataFrame([{'measure': 'Universities with at least one nearby listing', 'count': int(merged.n_listings.gt(0).sum())}, {'measure': 'Universities with no nearby listing', 'count': int(merged.n_listings.eq(0).sum())}, {'measure': 'Distinct vehicle listings matched', 'count': listing_links.listing_key.nunique()}, {'measure': 'Vehicle listings unmatched', 'count': len(vehicles) - listing_links.listing_key.nunique()}, {'measure': 'University–listing pairs', 'count': len(listing_links)}, {'measure': 'Listings shared by multiple universities', 'count': int(listing_links.groupby('listing_key').unitid.nunique().gt(1).sum())}])
    mo.output.append(mo.vstack([mo.md(f'### Spatial matching audit\nGraduate count was inferred as zero for {inferred_zero_graduate_count:,} institutions only when undergraduate enrollment equals total enrollment. Other missing graduate counts remain unknown. No nearby listings means a zero listing count but missing market shares/ages.'), mo.ui.table(spatial_audit, selection=None), mo.ui.table(merged, selection=None, page_size=10)]))
    return (spatial_audit,)

@app.cell
def _(mo):
    mo.output.append(mo.md('## Data visualisation\n    All figures below describe this provisional merged table. They are not statistical tests. For brand/body-style composition figures, the plotted value is the mean university-level share, so large listing markets do not automatically dominate. Neighborhoods can overlap. Minimum 10 known observations is a provisional display threshold; schools excluded from a figure remain in the merged table.\n    '))
    return

@app.cell
def _(mo, pd, np, plt, merged):
    plot_data = merged.copy()
    plot_data['international_group'] = pd.cut(plot_data.international_student_share, [-np.inf, *plot_data.international_student_share.quantile([.25,.5,.75]).to_list(), np.inf], labels=['Q1 lowest', 'Q2', 'Q3', 'Q4 highest'])
    plot_data['graduate_group'] = pd.cut(plot_data.graduate_student_share, [-np.inf, *plot_data.graduate_student_share.quantile([.25,.5,.75]).to_list(), np.inf], labels=['Q1 lowest', 'Q2', 'Q3', 'Q4 highest'])
    brand_cols = [c for c in merged if c.startswith('brand_share_')]
    top_brands = merged[brand_cols].mean().nlargest(6).index.tolist()
    rq1_data = plot_data[plot_data.n_known_brand.ge(10)]
    brand_plot = rq1_data.groupby('international_group', observed=True)[top_brands].mean().rename(columns=lambda x: x.replace('brand_share_', ''))
    fig_brand, ax_brand = plt.subplots(figsize=(10, 4.5))
    brand_plot.plot.bar(ax=ax_brand)
    ax_brand.set(title='RQ1: Nearby brand shares by international student share', xlabel='International student share quartile', ylabel='Mean university-level brand share')
    ax_brand.tick_params(axis='x', rotation=0)
    ax_brand.legend(title='Brand', bbox_to_anchor=(1.02, 1))
    fig_brand.tight_layout()
    mo.output.append(mo.vstack([mo.as_html(fig_brand), mo.md(f'This figure compares six commonly identified brands across international-student-share quartiles using {len(rq1_data):,} universities with at least 10 known-brand listings. The displayed mean shares span {brand_plot.min().min():.1%} to {brand_plot.max().max():.1%}; differences are descriptive and may reflect partial-source coverage, vehicle prices, or geography rather than student preferences.')]))
    return (plot_data, fig_brand)

@app.cell
def _(mo, plt, plot_data):
    _body_columns = [c for c in plot_data if c.startswith('body_style_share_')]
    _body_top = plot_data[_body_columns].mean().nlargest(5).index.tolist()
    _body_data = plot_data[plot_data.n_known_body_style.ge(10)]
    _body_summary = _body_data.groupby('graduate_group', observed=True)[_body_top].mean().rename(columns=lambda x: x.replace('body_style_share_', ''))
    fig_body, _ax = plt.subplots(figsize=(10, 4.5))
    _body_summary.plot.bar(ax=_ax)
    _ax.set(title='RQ2: Nearby body styles by graduate student share', xlabel='Graduate student share quartile', ylabel='Mean university-level body-style share')
    _ax.tick_params(axis='x', rotation=0)
    _ax.legend(title='Body style', bbox_to_anchor=(1.02, 1))
    fig_body.tight_layout()
    mo.output.append(mo.vstack([mo.as_html(fig_body), mo.md(f'The figure compares body-style compositions across graduate-share quartiles for {len(_body_data):,} universities. Only five common categories are shown, so their shares need not sum to one. Unknown body styles are excluded from the denominator and their coverage is reported above.')]))
    return (fig_body,)

@app.cell
def _(mo, plt, plot_data, pd):
    _age_data = plot_data[plot_data.n_known_vehicle_age.ge(10) & plot_data.graduate_group.notna()]
    _age_groups = [_age_data.loc[_age_data.graduate_group.eq(label), 'vehicle_age_median'].dropna().to_numpy() for label in ['Q1 lowest', 'Q2', 'Q3', 'Q4 highest']]
    fig_age, _ax = plt.subplots(figsize=(9, 4.5))
    _ax.boxplot(_age_groups, tick_labels=['Q1 lowest', 'Q2', 'Q3', 'Q4 highest'])
    _ax.set(title='RQ2: University market median vehicle ages', xlabel='Graduate student share quartile', ylabel='University-level median vehicle age (years)')
    fig_age.tight_layout()
    age_summary = _age_data.groupby('graduate_group', observed=True)[['vehicle_age_median', 'vehicle_age_q25', 'vehicle_age_q75']].median()
    mo.output.append(mo.vstack([mo.as_html(fig_age), mo.ui.table(age_summary.reset_index(), selection=None), mo.md(f'This plot shows variation in market median age across {len(_age_data):,} universities, rather than the age of every individual vehicle. The accompanying table also shows typical within-market quartiles. Use both when describing age distributions; a full-sample rerun is needed before interpreting group differences.')]))
    return (fig_age, age_summary)

@app.cell
def _(mo, plt, merged):
    _density_data = merged[merged.n_known_brand.ge(10)].dropna(subset=['japanese_brand_share'])
    fig_density, _ax = plt.subplots(figsize=(9, 4.5))
    _points = _ax.scatter(_density_data.nearby_college_count, _density_data.japanese_brand_share, s=14, alpha=0.4, c=_density_data.n_known_brand, cmap='viridis')
    _ax.set(title='RQ3: College density and nearby Japanese-brand share', xlabel='Number of selected universities within 10 miles (including focal university)', ylabel='Japanese-brand share among known-brand listings')
    fig_density.colorbar(_points, ax=_ax, label='Known-brand listings')
    fig_density.tight_layout()
    mo.output.append(mo.vstack([mo.as_html(fig_density), mo.md(f'Each point is one of {len(_density_data):,} university neighborhoods. Nearby college counts range from {int(_density_data.nearby_college_count.min())} to {int(_density_data.nearby_college_count.max())}; Japanese-brand shares range from {_density_data.japanese_brand_share.min():.1%} to {_density_data.japanese_brand_share.max():.1%}. A consistent upward pattern would support RQ3. This provisional plot does not establish such a relationship or a causal explanation.')]))
    return (fig_density,)

@app.cell
def _(mo, merged, alternative_5mi, complete_case_market, complete_listings, vehicles, pd):
    radius_comparison = pd.DataFrame([{'radius_miles': 5, 'universities_with_listings': int(alternative_5mi.n_listings.gt(0).sum()), 'university_listing_pairs': int(alternative_5mi.n_listings.sum())}, {'radius_miles': 10, 'universities_with_listings': int(merged.n_listings.gt(0).sum()), 'university_listing_pairs': int(merged.n_listings.sum())}])
    _paired = merged[['unitid', 'japanese_brand_share']].merge(alternative_5mi[['unitid', 'japanese_brand_share']], on='unitid', suffixes=('_10', '_5')).dropna()
    _radius_change = (_paired.japanese_brand_share_10 - _paired.japanese_brand_share_5).abs().median()
    _matched = merged.n_listings.gt(0)
    mo.output.append(mo.md(f'## Decision log\n    These are provisional processing decisions for the current workflow; the team should review them after the completed-sample rerun.\n\n    ### 1. Neighborhood radius\n    **Decision:** Use a 10-mile neighborhood for the main descriptive table.  \n    **Alternative:** Use a 5-mile neighborhood.  \n    **Evidence:** The code actually runs both radii. The 10-mile rule matches {_matched.sum():,} universities, versus {alternative_5mi.n_listings.gt(0).sum():,} at 5 miles.  \n    **Consequence:** Among {len(_paired):,} universities with identifiable brand data at both radii, the median absolute change in Japanese-brand share is {_radius_change:.2%}. This demonstrates sensitivity in the provisional input; it does not prove 10 miles is the uniquely correct definition.\n\n    ### 2. Attribute missingness\n    **Decision:** Retain listings with missing brand, body style, or age and use a separate known-field denominator for each measure.  \n    **Alternative:** Require all three fields to be available.  \n    **Evidence:** {len(complete_listings):,} of {len(vehicles):,} input listings satisfy the complete-case rule. The spatial summary is actually recomputed with those records.  \n    **Consequence:** Complete-case filtering changes matched university coverage from {_matched.sum():,} to {complete_case_market.n_listings.gt(0).sum():,}. It excludes {len(vehicles) - len(complete_listings):,} listings that may still inform one or two of the research questions.\n\n    ### 3. Unmatched universities\n    **Decision:** Keep the selected university universe in a left join; show zero listing counts and missing market characteristics for unmatched universities.  \n    **Alternative:** Retain only universities with a matched listing (an inner-join analysis table).  \n    **Evidence:** {int((~_matched).sum()):,} of {len(merged):,} universities have no matched provisional listing.  \n    **Consequence:** The alternative removes those universities. Mean international student share is {merged.international_student_share.mean():.2%} in the retained universe and {merged.loc[_matched, 'international_student_share'].mean():.2%} among matched universities. A missing market in this partial sample must not be interpreted as absence of a real local market.\n    '))
    mo.output.append(mo.ui.table(radius_comparison, selection=None))
    return (radius_comparison,)
if __name__ == '__main__':
    app.run()
